<script setup lang="ts">import { onMounted, ref } from "vue"; import { useRoute } from "vue-router"; import { getHistory } from "../../api"; const route = useRoute(); const events = ref<Awaited<ReturnType<typeof getHistory>>>([]); onMounted(async () => { events.value = await getHistory(String(route.params.id)); });</script><template><section class="detail-tab"><h2>Historial</h2><ul class="customer-repair-items"><li v-for="event in events" :key="event.id"><strong>{{ event.status }}</strong><span>{{ event.note || "Cambio de estado" }}</span><em>{{ new Date(event.createdAt).toLocaleString("es-ES") }}</em></li></ul><p v-if="!events.length" class="empty">No hay eventos registrados.</p></section></template>